package com.tradingsimulator.tradingengine.botstrategies; import com.tradingsimulator.model.*; import java.math.BigDecimal; import java.util.List; public final class MovingAverageCrossoverStrategy extends BaseStrategy { public MovingAverageCrossoverStrategy(int p){super(p);} public OrderSide signal(List<BigDecimal> ps){if(ps.size()<period+1)return null; BigDecimal prev=ps.subList(ps.size()-period-1,ps.size()-1).stream().reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(period)); BigDecimal now=ps.subList(ps.size()-period,ps.size()).stream().reduce(BigDecimal.ZERO,BigDecimal::add).divide(BigDecimal.valueOf(period)); return now.compareTo(prev)>0?OrderSide.BUY:now.compareTo(prev)<0?OrderSide.SELL:null;} }
